//! The CPU mirror of the shared prelude (`shaders/wgsl/lib/prelude.wgsl`, generated by `ledger::gen::prelude`) and of
//! the presentation layer (`shaders/wgsl/lib/present.wgsl`, hand-written; render contract Part 5, "Presentation
//! layer"), for the assertions that compare the shaders with it. Each function computes, in f64, what its WGSL namesake
//! computes in f32, from the same definitions (render contract Part 5's renderings, R-72; render_gui_spec §10.1;
//! dd_colouring §3.1, §3.7): the arithmetic is written here again, not shared, so a slip in either shows as a
//! disagreement. The colour-space maps are [`crate::colour::space`]'s, the one Rust source of dd_colouring §3.1's
//! transforms, in f64. The data the shaders embed, the published LUT stops (R-122) and the proposed hatch
//! (REQ-COL-055), is read from the ledger that generates them; the hand-written layer's constants, the "not yet" grey
//! and its stipple (REQ-COL-053, REQ-COL-064), the NaN / Inf style (REQ-COL-110) and the presentation views' invalid
//! colour (R-467), are written here again, and the tests compare them. Colours are linear
//! RGB unless a name says sRGB.

use ledger::constants::{HUE_WHEEL_C, HUE_WHEEL_L};
use ledger::gen::numeric::non_finite;
use ledger::gen::prelude;

use crate::colour::space;

/// An RGB triple.
pub type Rgb = [f64; 3];

/// The sRGB transfer, encoded to linear (dd_colouring §3.1), in f64: [`space::srgb_to_linear`].
pub fn srgb_to_linear(c: f64) -> f64 {
    space::srgb_to_linear(c)
}

/// The sRGB transfer's inverse, linear to encoded (dd_colouring §3.1), in f64: [`space::linear_to_srgb`].
pub fn linear_to_srgb(c: f64) -> f64 {
    space::linear_to_srgb(c)
}

/// [`srgb_to_linear`] on each channel.
pub fn srgb_to_linear3(c: Rgb) -> Rgb {
    c.map(srgb_to_linear)
}

/// An 8-bit sRGB colour, decoded to linear.
pub fn srgb8(c: [u8; 3]) -> Rgb {
    c.map(|x| srgb_to_linear(f64::from(x) / 255.0))
}

/// dd_colouring §3.1's `M₁⁻¹`: LMS to linear sRGB ([`space::OKLAB`]'s).
pub const LMS_TO_LINEAR: [[f64; 3]; 3] = space::OKLAB.m1_inv;

/// OKLab to linear sRGB (dd_colouring §3.1), in f64: [`space::oklab_to_linear`].
pub fn oklab_to_linear(lab: Rgb) -> Rgb {
    space::oklab_to_linear(lab)
}

/// Linear sRGB to OKLab (dd_colouring §3.1), in f64, for distances between colours: [`space::linear_to_oklab`].
pub fn linear_to_oklab(rgb: Rgb) -> Rgb {
    space::linear_to_oklab(rgb)
}

/// OKLCH to linear sRGB, the hue `turns` in turns: [`space::oklch_to_oklab`] at `2π · turns` radians, then
/// [`oklab_to_linear`].
pub fn oklch_to_linear(l: f64, c: f64, turns: f64) -> Rgb {
    oklab_to_linear(space::oklch_to_oklab([l, c, std::f64::consts::TAU * turns]))
}

/// `range_norm(x, lo, hi, auto_range, meas)` (render_gui_spec §10.1): `clamp((x − l)/(h − l), 0, 1)` with `(l, h)` the
/// measured `meas` when `auto_range`, else `(lo, hi)`; 0 for a degenerate range, `h = l` (R-72).
pub fn range_norm(x: f64, lo: f64, hi: f64, auto_range: bool, meas: [f64; 2]) -> f64 {
    let (l, h) = if auto_range {
        (meas[0], meas[1])
    } else {
        (lo, hi)
    };
    if h == l {
        0.0
    } else {
        ((x - l) / (h - l)).clamp(0.0, 1.0)
    }
}

/// A LUT ramp over `stops` (sRGB-encoded) at `t`: `t` clamped to [0, 1], the stops at `k/(N − 1)`, interpolated
/// linearly in sRGB, then decoded to linear RGB.
pub fn ramp(stops: &[Rgb], t: f64) -> Rgb {
    let last = stops.len() - 1;
    let x = t.clamp(0.0, 1.0) * last as f64;
    let k = (x.floor() as usize).min(last - 1);
    let f = x - k as f64;
    let (a, b) = (stops[k], stops[k + 1]);
    srgb_to_linear3([0, 1, 2].map(|c| a[c] + (b[c] - a[c]) * f))
}

/// The published viridis stops (R-122), from the ledger's data file.
pub fn viridis_stops() -> Vec<Rgb> {
    prelude::luts()[0].stops()
}

/// The published twilight stops (R-122), from the ledger's data file.
pub fn twilight_stops() -> Vec<Rgb> {
    prelude::luts()[1].stops()
}

/// The published magma stops (R-122), from the ledger's data file: `s_impurity`'s ramp (colour_composition §6).
pub fn magma_stops() -> Vec<Rgb> {
    prelude::luts()[2].stops()
}

/// Moreland's published cool-warm stops (R-122), from the ledger's data file: the ramp of a numeric view whose field's
/// declared range spans zero (R-400).
pub fn coolwarm_stops() -> Vec<Rgb> {
    prelude::luts()[3].stops()
}

/// `ramp_viridis(t)`.
pub fn ramp_viridis(t: f64) -> Rgb {
    ramp(&viridis_stops(), t)
}

/// `ramp_twilight(t)`.
pub fn ramp_twilight(t: f64) -> Rgb {
    ramp(&twilight_stops(), t)
}

/// `ramp_magma(t)`.
pub fn ramp_magma(t: f64) -> Rgb {
    ramp(&magma_stops(), t)
}

/// `ramp_coolwarm(t)`: its midpoint, `t = ½`, the table's neutral, stop 16 of 33.
pub fn ramp_coolwarm(t: f64) -> Rgb {
    ramp(&coolwarm_stops(), t)
}

/// `ramp_grey(t)`: OKLab `(t, 0, 0)`, `t` clamped to [0, 1].
pub fn ramp_grey(t: f64) -> Rgb {
    oklab_to_linear([t.clamp(0.0, 1.0), 0.0, 0.0])
}

/// `hue_wheel(t)`: OKLCH at the register's `(L, C)`, hue `t` turns.
pub fn hue_wheel(t: f64) -> Rgb {
    let (l, c) = (HUE_WHEEL_L.number(), HUE_WHEEL_C.number());
    oklch_to_linear(l, c, t)
}

/// Which of the hatch's two colours `debug_invalid` draws at the pixel `frag_xy`: stripe `⌊(⌊x⌋ + ⌊y⌋) / w⌋ mod 2`,
/// `w` the stripe width.
pub fn hatch_stripe(frag_xy: [f64; 2]) -> usize {
    let w = i64::from(prelude::hatch().half_period);
    let s = frag_xy[0].floor() as i64 + frag_xy[1].floor() as i64;
    s.div_euclid(w).rem_euclid(2) as usize
}

/// `debug_invalid(frag_xy)`: the proposed hatch's colour at the pixel (REQ-COL-055; R-132, R-136).
pub fn debug_invalid(frag_xy: [f64; 2]) -> Rgb {
    srgb8(prelude::hatch().colours[hatch_stripe(frag_xy)])
}

/// The neutral "not yet" grey of running samples (R-96; colour_composition §1.4) and of `d_min`'s unset value (R-280),
/// the ground of the "not yet" style ([`debug_not_yet`], R-399), as 8-bit sRGB: `#4E4E4E`, OKLab lightness 0.424.
/// Proposed, R-71 (REQ-COL-053, RQ-233): among the 8-bit greys it is the one farthest in OKLab from its nearest outcome
/// class or hatch colour: 0.230 from `#3462E0` (collision 1–2) and 0.231 from `#141418` (bounded), and 0.101 from the
/// viridis ramp; the evidence is `render/tests/not_yet_grey.rs`'s. Confirmed by the human at the M1 gate (R-433).
/// `present.wgsl`'s `DBG_NOT_YET` is its linear value.
pub const NOT_YET_SRGB8: [u8; 3] = [0x4e, 0x4e, 0x4e];

/// `DBG_NOT_YET`: [`NOT_YET_SRGB8`], decoded to linear.
pub fn not_yet() -> Rgb {
    srgb8(NOT_YET_SRGB8)
}

/// The "not yet" style's dots (R-399), as 8-bit sRGB: `#909090`, OKLab lightness 0.653, 0.229 above the grey. Proposed,
/// R-71 (REQ-COL-064), as `#808080`; confirmed by the human at the M1 gate with the dots changed to `#909090` (R-434),
/// so that no flat palette colour comes within the hatch's τ = 0.101 (R-429) of every pixel of a 4 × 4 block: the
/// nearest is 0.115 from its farthest pixel (`render/tests/not_yet_style.rs`). `present.wgsl`'s `DBG_NOT_YET_DOT` is
/// its linear value.
pub const NOT_YET_DOT_SRGB8: [u8; 3] = [0x90, 0x90, 0x90];

/// The stipple's cell, in pixels: one dot in each `NOT_YET_CELL` × `NOT_YET_CELL` cell, at its corner. Confirmed at
/// the M1 gate (R-434).
pub const NOT_YET_CELL: i64 = 4;

/// The stipple's dot, in pixels: `NOT_YET_DOT` × `NOT_YET_DOT`. Confirmed at the M1 gate (R-434).
pub const NOT_YET_DOT: i64 = 2;

/// `DBG_NOT_YET_DOT`: [`NOT_YET_DOT_SRGB8`], decoded to linear.
pub fn not_yet_dot() -> Rgb {
    srgb8(NOT_YET_DOT_SRGB8)
}

/// Whether `debug_not_yet` draws a dot at the pixel `frag_xy` (REQ-COL-064; confirmed, R-434): `p = ⌊frag_xy⌋` in the
/// first [`NOT_YET_DOT`] pixels of its [`NOT_YET_CELL`]-pixel cell along both axes.
pub fn not_yet_dot_at(frag_xy: [f64; 2]) -> bool {
    frag_xy
        .iter()
        .all(|&c| (c.floor() as i64).rem_euclid(NOT_YET_CELL) < NOT_YET_DOT)
}

/// `debug_not_yet(frag_xy)`: the "not yet" style (R-399), the grey with a fine dot stipple from the pixel position.
pub fn debug_not_yet(frag_xy: [f64; 2]) -> Rgb {
    if not_yet_dot_at(frag_xy) {
        not_yet_dot()
    } else {
        not_yet()
    }
}

/// The NaN / Inf style's two colours, as 8-bit sRGB (REQ-COL-110; R-467 D6, R-505): indigo `#6000F4`, OKLab lightness
/// 0.486, drawn where `⌊x⌋ / 4` and `⌊y⌋ / 4` have one parity, and dark green `#004000`, 0.322, where they differ.
/// Proposed, R-71, by TASK-M2-34, for the M2 gate (R-504): each the 8-bit colour near its seed farthest in OKLab from
/// every palette entry REQ-COL-055 measures, the hatch's and the stipple's colours and `#FF00FF`, indigo 0.117 from its
/// nearest and green 0.109, and each farther than τ = 0.101 from `#FF00FF` under every simulation; the measurement is
/// `render/tests/debug_view_styles.rs`'s. `present.wgsl`'s `DBG_NAN_INF_INDIGO` and `DBG_NAN_INF_GREEN` are their
/// linear values.
pub const NAN_INF_SRGB8: [[u8; 3]; 2] = [[0x60, 0x00, 0xf4], [0x00, 0x40, 0x00]];

/// The NaN / Inf style's square, in pixels (REQ-COL-110, proposed): a checkerboard of `NAN_INF_CELL` ×
/// `NAN_INF_CELL` squares.
pub const NAN_INF_CELL: i64 = 4;

/// Which of the NaN / Inf style's two colours `debug_nan_inf` draws at the pixel `frag_xy`: 0, indigo, where
/// `⌊x⌋ / NAN_INF_CELL` and `⌊y⌋ / NAN_INF_CELL` have one parity, 1, green, where they differ: the low bits'
/// exclusive or, as `present.wgsl` takes it.
pub fn nan_inf_square(frag_xy: [f64; 2]) -> usize {
    let [x, y] = frag_xy.map(|c| (c.floor() as i64).div_euclid(NAN_INF_CELL));
    ((x ^ y) & 1) as usize
}

/// `debug_nan_inf(frag_xy)`: the debug view's style for a non-finite sample (R-467 D6; REQ-COL-110), the
/// checkerboard's colour at the pixel.
pub fn debug_nan_inf(frag_xy: [f64; 2]) -> Rgb {
    srgb8(NAN_INF_SRGB8[nan_inf_square(frag_xy)])
}

/// The presentation views' invalid colour, as 8-bit sRGB (R-467 clause 2, D4; REQ-COL-108): bounded / nothing yet's
/// black `#141418` (colour_composition §1.4), drawn for a `sim_failed` sample, a reserved `state` code, a non-finite
/// value and a ramp's or compaction's invalid value in place of the hatch, unless the node overrides its invalid colour.
/// `present.wgsl`'s `PRESENT_INVALID` is its linear value.
pub const PRESENT_INVALID_SRGB8: [u8; 3] = [0x14, 0x14, 0x18];

/// `PRESENT_INVALID`: [`PRESENT_INVALID_SRGB8`], decoded to linear.
pub fn present_invalid() -> Rgb {
    srgb8(PRESENT_INVALID_SRGB8)
}

/// The canvas background's default, as 8-bit sRGB (R-467 D2; REQ-COL-108): `#0A0A0A`, the colour the GUI clears its
/// window to, `gui::app::clear_colour`, egui 0.36's dark theme's `extreme_bg_color`, `Color32::from_gray(10)`. The
/// render's background is a uniform its caller sets (`ledger::gen::prelude::uniform_words_with`); this is the value a
/// caller that sets none draws, and the one the golden harness records (`validation::golden_scene`).
pub const CANVAS_BACKGROUND_SRGB8: [u8; 3] = [0x0a, 0x0a, 0x0a];

/// [`CANVAS_BACKGROUND_SRGB8`], decoded to linear, as the f32 the uniform holds.
pub fn canvas_background() -> [f32; 3] {
    srgb8(CANVAS_BACKGROUND_SRGB8).map(|c| c as f32)
}

/// The canonical quiet NaN's bits (lowering Part 3a), the absence sentinel.
pub const ABSENT_NAN_BITS: u32 = 0x7fc0_0000;

/// The Okabe–Ito palette (Okabe & Ito 2002), 8-bit sRGB, in its published order.
pub const OKABE_ITO: [[u8; 3]; 8] = [
    [0, 0, 0],
    [230, 159, 0],
    [86, 180, 233],
    [0, 158, 115],
    [240, 228, 66],
    [0, 114, 178],
    [213, 94, 0],
    [204, 121, 167],
];

/// The golden-angle hue of class `i`, in turns: `frac(i · φ_g)`, `φ_g = (√5 − 1)/2` (dd_colouring §3.7).
pub fn golden_turns(i: u32) -> f64 {
    let phi = (5f64.sqrt() - 1.0) / 2.0;
    (f64::from(i) * phi).fract()
}

/// `dbg_cat(i, n)`: Okabe–Ito, cycling, for `n ≤ 8`; the golden angle on `hue_wheel` for every class when `n > 8`.
pub fn dbg_cat(i: u32, n: u32) -> Rgb {
    if n <= 8 {
        srgb8(OKABE_ITO[(i % 8) as usize])
    } else {
        hue_wheel(golden_turns(i))
    }
}

/// `dbg_lin(x, lo, hi)`: `x` on the fixed range, clamped, on the viridis ramp.
pub fn dbg_lin(x: f64, lo: f64, hi: f64) -> Rgb {
    ramp_viridis(range_norm(x, lo, hi, false, [0.0, 0.0]))
}

/// `dbg_log`'s place on the ramp: `1 − 1/(1 + ln(1 + |x|/eps))`.
pub fn dbg_log_t(x: f64, eps: f64) -> f64 {
    1.0 - 1.0 / (1.0 + (1.0 + x.abs() / eps).ln())
}

/// `dbg_log(x, eps)`.
pub fn dbg_log(x: f64, eps: f64) -> Rgb {
    ramp_viridis(dbg_log_t(x, eps))
}

/// `dbg_flag(b)`: Okabe–Ito's bluish green for true, vermillion for false.
pub fn dbg_flag(b: bool) -> Rgb {
    srgb8(if b { OKABE_ITO[3] } else { OKABE_ITO[6] })
}

/// The PCG hash (Jarzynski and Olano 2020, `pcg_hash`).
pub fn pcg(v: u32) -> u32 {
    let state = v.wrapping_mul(747_796_405).wrapping_add(2_891_336_453);
    let word = ((state >> ((state >> 28) + 4)) ^ state).wrapping_mul(277_803_737);
    (word >> 22) ^ word
}

/// `dbg_bytes_rgb(h)`: the hash's low three bytes, low first, as 8-bit sRGB red, green, blue.
pub fn dbg_bytes_rgb(h: u32) -> Rgb {
    let h = h.to_le_bytes();
    srgb8([h[0], h[1], h[2]])
}

/// `dbg_hash_u32(v)`: the hash's low three bytes as 8-bit sRGB red, green, blue.
pub fn dbg_hash_u32(v: u32) -> Rgb {
    dbg_bytes_rgb(pcg(v))
}

/// The whole-word fold of `dbg_hash_word` (REQ-TOOL-155): `pcg(w ^ pcg(z ^ pcg(y ^ pcg(x))))` over the word's four
/// limbs, `x` first.
pub fn word_hash(w: [u32; 4]) -> u32 {
    pcg(w[3] ^ pcg(w[2] ^ pcg(w[1] ^ pcg(w[0]))))
}

/// `dbg_hash_word(w)`: [`word_hash`], then the byte-to-RGB step.
pub fn dbg_hash_word(w: [u32; 4]) -> Rgb {
    dbg_bytes_rgb(word_hash(w))
}

/// Whether `x` is the absence NaN, by its exact bits.
fn absent(x: f32) -> bool {
    x.to_bits() == ABSENT_NAN_BITS
}

/// `dbg_ternary(m, frag_xy)` (REQ-TOOL-154): `m / max(mᵢ)` as linear RGB; the hatch where no mass is positive or one
/// is the absence NaN.
pub fn dbg_ternary(m: [f32; 3], frag_xy: [f64; 2]) -> Rgb {
    let top = m[0].max(m[1]).max(m[2]);
    if m.iter().any(|&x| absent(x)) || top.is_nan() || top <= 0.0 {
        return debug_invalid(frag_xy);
    }
    m.map(|x| f64::from(x) / f64::from(top))
}

/// `dbg_dircos3(v, frag_xy)`: `½(v̂ + 1)` as linear RGB; the hatch where `‖v‖ > 0` fails or a component is the absence
/// NaN.
pub fn dbg_dircos3(v: [f32; 3], frag_xy: [f64; 2]) -> Rgb {
    // A component that is the absence NaN, or any NaN, makes the norm NaN: in f64 that needs no bit test, which the
    // shader makes because fast math may fold its NaN test (R-343).
    let v = v.map(f64::from);
    let norm = (v[0] * v[0] + v[1] * v[1] + v[2] * v[2]).sqrt();
    if norm.is_nan() || norm <= 0.0 {
        return debug_invalid(frag_xy);
    }
    v.map(|x| 0.5 * (x / norm + 1.0))
}

/// `dbg_dircos6(v, frag_xy)` (REQ-TOOL-157): each body's squared norm `wᵢ = ‖vᵢ‖²` over `max(wᵢ)`, as linear RGB; the
/// hatch where `‖v‖ > 0` fails or a component is the absence NaN.
pub fn dbg_dircos6(v: [[f32; 2]; 3], frag_xy: [f64; 2]) -> Rgb {
    let w = v.map(|b| f64::from(b[0]).powi(2) + f64::from(b[1]).powi(2));
    let top = w[0].max(w[1]).max(w[2]);
    if v.iter().flatten().any(|&x| absent(x)) || top.is_nan() || top <= 0.0 {
        return debug_invalid(frag_xy);
    }
    w.map(|x| x / top)
}

/// `dbg_literal(x)`: `0.5 + 0.5 · x/(1 + |x|)`, `x` clamped to ±1e30.
pub fn dbg_literal(x: f64) -> f64 {
    let c = x.clamp(-1e30, 1e30);
    0.5 + 0.5 * c / (1.0 + c.abs())
}

/// `dbg_sentinel(x, frag_xy)`: the hatch for the absence NaN's exact bits, else `x` on the viridis ramp
/// ([`dbg_literal`]).
pub fn dbg_sentinel(x: f32, frag_xy: [f64; 2]) -> Rgb {
    if x.to_bits() == ABSENT_NAN_BITS {
        debug_invalid(frag_xy)
    } else {
        ramp_viridis(dbg_literal(f64::from(x)))
    }
}

// ── The drift views (render contract Part 5, "Presentation layer"; R-379, R-381; REQ-TOOL-149; TASK-M3-05) ──────────

/// The drift views' `symlog` compaction, the `COMPACTION` uniform's default (R-381): `drift.wgsl`'s `DBG_DRIFT_SYMLOG`.
pub const DRIFT_SYMLOG: u32 = 0;

/// The drift views' `lin` compaction override: `drift.wgsl`'s `DBG_DRIFT_LIN`.
pub const DRIFT_LIN: u32 = 1;

/// The drift views' `log` compaction override: `drift.wgsl`'s `DBG_DRIFT_LOG`.
pub const DRIFT_LOG: u32 = 2;

/// The drift views' `diverging(c−, c0, c+)` colours, 8-bit sRGB (render contract Part 5; R-72): Moreland's cool-warm
/// ends and neutral, `#3B4CC0`, `#DDDDDD` and `#B40426`, the colours `drift.wgsl`'s `dbg_drift_ramp` decodes.
pub const DRIFT_DIVERGING_SRGB8: [[u8; 3]; 3] =
    [[0x3b, 0x4c, 0xc0], [0xdd, 0xdd, 0xdd], [0xb4, 0x04, 0x26]];

/// The drift views' `diverging` ramp, its colours [`DRIFT_DIVERGING_SRGB8`] decoded to linear.
pub fn drift_diverging() -> crate::colour::field_ramp::Ramp {
    let [lo, mid, hi] = DRIFT_DIVERGING_SRGB8.map(srgb8);
    crate::colour::field_ramp::Ramp::Diverging { lo, mid, hi }
}

/// `dbg_drift_ramp(t, viridis)`: the drift views' `diverging` ramp at `t`, or viridis under the palette swap.
pub fn drift_ramp(t: f64, viridis: bool) -> Rgb {
    if viridis {
        ramp_viridis(t)
    } else {
        drift_diverging().colour(t)
    }
}

/// `dbg_drift_place(x, compaction, lin_r, eps)`: the drift's place on its ramp, `x` clamped to ±1e30. `symlog`, the
/// default and any value but [`DRIFT_LIN`] and [`DRIFT_LOG`]: `dbg_literal(sign(x)·ln(1 + |x|/eps))`; `lin`:
/// `range_norm(x, −lin_r, lin_r, false, ·)`; `log`: `dbg_log`'s place of `|x|`.
pub fn dbg_drift_place(x: f64, compaction: u32, lin_r: f64, eps: f64) -> f64 {
    let c = x.clamp(-1e30, 1e30);
    let s = (1.0 + c.abs() / eps).ln();
    match compaction {
        DRIFT_LIN => range_norm(c, -lin_r, lin_r, false, [0.0, 0.0]),
        DRIFT_LOG => 1.0 - 1.0 / (1.0 + s),
        _ => dbg_literal(if c >= 0.0 { s } else { -s }),
    }
}

/// `dbg_drift(x, compaction, viridis, lin_r, eps, frag_xy)`: the hatch for the absence NaN's exact bits; else the
/// drift's place on `diverging`, on viridis under the palette swap, and on viridis always under `log`.
pub fn dbg_drift(
    x: f32,
    compaction: u32,
    viridis: bool,
    lin_r: f64,
    eps: f64,
    frag_xy: [f64; 2],
) -> Rgb {
    if x.to_bits() == ABSENT_NAN_BITS {
        return debug_invalid(frag_xy);
    }
    let t = dbg_drift_place(f64::from(x), compaction, lin_r, eps);
    drift_ramp(t, viridis || compaction == DRIFT_LOG)
}

/// The neutral band's half-width as a fraction of the drift's reference: `k·2⁻²³`, `k = 128`, so 2⁻¹⁶ (render contract
/// Part 5, "The neutral band"; R-652): `drift.wgsl`'s `DBG_DRIFT_NEUTRAL_BAND`.
pub const DRIFT_NEUTRAL_BAND: f64 = 1.0 / 65_536.0;

/// `dbg_drift_shown(x, compaction, reference)`: under `symlog`, 0 where `|x| ≤ DRIFT_NEUTRAL_BAND·|reference|`, else `x`;
/// `lin`, `log` and a non-finite `x` or `reference`, tested on the bits first (R-436), pass `x` through.
pub fn dbg_drift_shown(x: f32, compaction: u32, reference: f32) -> f32 {
    if non_finite(x) || non_finite(reference) || compaction == DRIFT_LIN || compaction == DRIFT_LOG
    {
        return x;
    }
    if x.abs() <= (DRIFT_NEUTRAL_BAND as f32) * reference.abs() {
        0.0
    } else {
        x
    }
}

/// The suspect styling's period, in pixels: a line where the pixel's coordinate is a multiple of it.
pub const SUSPECT_PERIOD: i64 = 4;

/// The ramp output's relative luminance (Rec. 709's weights, linear RGB) at and above which the suspect styling's ink
/// is black, and below which it is white.
pub const SUSPECT_INK_SPLIT: f64 = 0.18;

/// Whether the suspect styling draws a line at the pixel `frag_xy`: a row where `SUSPECT_ENERGY` (`energy`) holds and
/// `⌊y⌋` is a multiple of [`SUSPECT_PERIOD`], a column where `SUSPECT_LZ` (`lz`) holds and `⌊x⌋` is one.
pub fn suspect_line(energy: bool, lz: bool, frag_xy: [f64; 2]) -> bool {
    let [x, y] = frag_xy.map(|c| (c.floor() as i64).rem_euclid(SUSPECT_PERIOD));
    (energy && y == 0) || (lz && x == 0)
}

/// The suspect styling's ink over the ramp output `rgb`: black where its relative luminance is at least
/// [`SUSPECT_INK_SPLIT`], white below.
pub fn suspect_ink(rgb: Rgb) -> Rgb {
    let y = 0.2126 * rgb[0] + 0.7152 * rgb[1] + 0.0722 * rgb[2];
    if y >= SUSPECT_INK_SPLIT {
        [0.0; 3]
    } else {
        [1.0; 3]
    }
}

/// `dbg_suspect(rgb, x, energy, lz, frag_xy)`: the suspect styling on a drift view's ramp output `rgb`, never on the
/// hatch (`x` the absence NaN): [`suspect_ink`] where [`suspect_line`] holds, `rgb` elsewhere.
pub fn dbg_suspect(rgb: Rgb, x: f32, energy: bool, lz: bool, frag_xy: [f64; 2]) -> Rgb {
    if x.to_bits() != ABSENT_NAN_BITS && suspect_line(energy, lz, frag_xy) {
        suspect_ink(rgb)
    } else {
        rgb
    }
}
